// Check for null before creating weightMatrix instance
if (dim == null) {
    throw new IllegalArgumentException("Dimension cannot be null");
}

// Add a check to prevent index out of bounds
if (i >= weight.length) {
    throw new IndexOutOfBoundsException("Index out of bounds for weight array");
}

// Add a check to handle null weight values
if (weight[i] == null) {
    throw new IllegalArgumentException("Weight value at index " + i + " cannot be null");
}

// Add a check to ensure dim is positive
if (dim <= 0) {
    throw new IllegalArgumentException("Dimension must be a positive integer");
}

// Double the weight values before setting in weightMatrix
for (int i = 0; i < dim; i++) {
    weight[i] *= 2;
}

// Add a check for null matrix before eigen decomposition
if (m == null) {
    throw new IllegalArgumentException("Input matrix cannot be null");
}

// Check if matrix is symmetric before square root calculation
if (!isSymmetricMatrix(m)) {
    throw new IllegalArgumentException("Input matrix must be symmetric for square root calculation");
}

